//! S07 tokenizer consumer battery over the frozen diverse fixtures (T02).
//!
//! Every expected token shape below is a **handwritten oracle** derived from the
//! fixture XML and the pinned `reader_tokenizer/v1` rule (maximal whitespace /
//! non-whitespace runs localized against the reading-order units) — never
//! generated by `reader_tokenizer`. The wire read-back parity test proves the
//! consumer builds from the saved cleaned wire JSONL only: the stream from
//! `tokenize_from_wire` equals the direct build, so no XML re-parse can be on
//! the read path.
//!
//! Non-claims: bounded to the self-authored non-legal synthetic fixtures in
//! `fixtures/reader/`; not corpus coverage, not normalization, not a
//! legal-completeness claim; R1000 stays active. Decoded text is compared in
//! memory only and never printed.

use ln_decode::analysis_source_mapping::SourceIdentity;
use ln_decode::cleaned_wire::{
    CLEANED_PROJECTION_SCHEMA, CleanedProjection, WireCompletion, WireLimits, read_cleaned_wire,
    render_cleaned_projection,
};
use ln_decode::document_context::DocumentVersionRef;
use ln_decode::reader_composite::CompositeAddress;
use ln_decode::reader_contract::ReaderRecordIndex;
use ln_decode::reader_projection::{ReaderProjection, ViewId, build_projection};
use ln_decode::reader_reading_order::ReadingOrderIndex;
use ln_decode::reader_tokenizer::{
    DocumentIdentity, ReaderToken, TokenClass, TokenStream, TokenUnit, TokenizerErrorKind,
    tokenize, tokenize_address, tokenize_from_wire, tokenize_projection,
};
use ln_decode::source_package::{Limits, Package, capture};

// ---------------------------------------------------------------- fixtures #

struct Fixture {
    file: &'static str,
    xml: &'static str,
}

const FIXTURES: &[Fixture] = &[
    Fixture {
        file: "text-only.xml",
        xml: include_str!("fixtures/reader/diverse/text-only.xml"),
    },
    Fixture {
        file: "controls.xml",
        xml: include_str!("fixtures/reader/diverse/controls.xml"),
    },
    Fixture {
        file: "fields-revisions.xml",
        xml: include_str!("fixtures/reader/diverse/fields-revisions.xml"),
    },
    Fixture {
        file: "residual-and-tails.xml",
        xml: include_str!("fixtures/reader/diverse/residual-and-tails.xml"),
    },
    Fixture {
        file: "encoding.xml",
        xml: include_str!("fixtures/reader/diverse/encoding.xml"),
    },
    Fixture {
        file: "empty-structure.xml",
        xml: include_str!("fixtures/reader/diverse/empty-structure.xml"),
    },
    Fixture {
        file: "mixed-wordml.xml",
        xml: include_str!("fixtures/reader/mixed-wordml.xml"),
    },
];

fn fixture(name: &str) -> &'static Fixture {
    FIXTURES
        .iter()
        .find(|entry| entry.file == name)
        .unwrap_or_else(|| panic!("fixture {name} is not declared"))
}

// ------------------------------------------------------------------ helpers #

fn identity() -> DocumentIdentity {
    let version = DocumentVersionRef::try_new(
        "doc-1".to_string(),
        "rev-1".to_string(),
        "reader_wordml_profile/v1".to_string(),
    )
    .expect("version triple must be valid");
    let source = SourceIdentity::try_new(
        "a".repeat(64),
        12,
        CLEANED_PROJECTION_SCHEMA.to_string(),
        None,
        None,
    )
    .expect("source identity must be valid");
    DocumentIdentity::new(source, version)
}

/// The independently-authored token shape used by the oracles.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Shape {
    Word,
    Space,
    Derived(&'static str),
    Composite(usize),
}

fn shape(token: &ReaderToken) -> Shape {
    match token {
        ReaderToken::Source { class, .. } => match class {
            TokenClass::Word => Shape::Word,
            TokenClass::Whitespace => Shape::Space,
        },
        ReaderToken::DerivedControl { derived_kind, .. } => Shape::Derived(derived_kind.as_str()),
        ReaderToken::Composite { units, .. } => Shape::Composite(units.len()),
    }
}

struct Built {
    package: Package,
    projection: ReaderProjection,
    cleaned: CleanedProjection,
    order: ReadingOrderIndex,
    stream: TokenStream,
}

fn build(fixture: &Fixture) -> Built {
    let package = capture(fixture.xml.as_bytes(), &Limits::default())
        .unwrap_or_else(|error| panic!("{} must capture: {error:?}", fixture.file));
    let projection = build_projection(package.records())
        .unwrap_or_else(|error| panic!("{} must project: {error:?}", fixture.file));
    let order = ReadingOrderIndex::build(&projection, package.records())
        .unwrap_or_else(|error| panic!("{} must order: {error:?}", fixture.file));
    let artifact = render_cleaned_projection(
        &package,
        &projection,
        &WireCompletion::Complete,
        &WireLimits::default(),
    )
    .unwrap_or_else(|error| panic!("{} must render: {error:?}", fixture.file));
    let cleaned = read_cleaned_wire(&artifact)
        .unwrap_or_else(|error| panic!("{} must read back: {error:?}", fixture.file));
    let stream = tokenize(&cleaned, &package, &identity())
        .unwrap_or_else(|error| panic!("{} must tokenize: {error:?}", fixture.file));
    Built {
        package,
        projection,
        cleaned,
        order,
        stream,
    }
}

fn shapes(stream: &TokenStream) -> Vec<Shape> {
    stream.tokens.iter().map(shape).collect()
}

/// The decoded text a token contributes to the clean channel.
fn token_text(token: &ReaderToken, index: &ReaderRecordIndex, view_output: &str) -> String {
    match token {
        ReaderToken::Source {
            fragment_ref, span, ..
        } => {
            let value = index
                .text(fragment_ref.as_str())
                .unwrap_or_else(|| panic!("fragment {fragment_ref} must exist"))
                .value
                .clone();
            value[span.start..span.end].to_string()
        }
        ReaderToken::DerivedControl { literal, .. } => (*literal).to_string(),
        ReaderToken::Composite {
            output_start,
            output_end,
            ..
        } => view_output[*output_start..*output_end].to_string(),
    }
}

// -------------------------------------------------------------- oracles #

#[test]
fn text_only_oracle() {
    let built = build(fixture("text-only.xml"));
    // "Только текст" -> word, whitespace, word.
    assert_eq!(
        shapes(&built.stream),
        vec![Shape::Word, Shape::Space, Shape::Word]
    );
    assert_eq!(built.stream.source_count(), 3);
    assert_eq!(built.stream.derived_count(), 0);
    assert_eq!(built.stream.composite_count(), 0);
}

#[test]
fn controls_oracle() {
    let built = build(fixture("controls.xml"));
    // Six paragraphs: "A" + control + "B". The documented controls are
    // page_break, three line breaks and a tab; the last-rendered hint is not a
    // control, so its paragraph's "A"+"B" forms a composite.
    let expected = vec![
        Shape::Word,
        Shape::Derived("page_break"),
        Shape::Word,
        Shape::Word,
        Shape::Derived("line_break"),
        Shape::Word,
        Shape::Word,
        Shape::Derived("line_break"),
        Shape::Word,
        Shape::Word,
        Shape::Derived("line_break"),
        Shape::Word,
        Shape::Composite(2),
        Shape::Word,
        Shape::Derived("tab"),
        Shape::Word,
    ];
    assert_eq!(shapes(&built.stream), expected);
    assert_eq!(built.stream.source_count(), 10);
    assert_eq!(built.stream.derived_count(), 5);
    assert_eq!(built.stream.composite_count(), 1);
}

#[test]
fn encoding_oracle() {
    let built = build(fixture("encoding.xml"));
    // "Привет" + tab + "мир" + line break + "!"; then three adjacent fragments
    // "Ж" + "é" + "😀" (a composite); then "NBSP:" + NBSP + "Mu".
    let expected = vec![
        Shape::Word,
        Shape::Derived("tab"),
        Shape::Word,
        Shape::Derived("line_break"),
        Shape::Word,
        Shape::Composite(3),
        Shape::Word,
        Shape::Space,
        Shape::Word,
    ];
    assert_eq!(shapes(&built.stream), expected);
}

#[test]
fn fields_and_revisions_oracle() {
    let built = build(fixture("fields-revisions.xml"));
    // Field codes "HYPERLINK" + " " + "\"target\"" (never body text), then the
    // adjacent revision insertion/deletion pair as a composite.
    let expected = vec![Shape::Word, Shape::Space, Shape::Word, Shape::Composite(2)];
    assert_eq!(shapes(&built.stream), expected);
}

#[test]
fn residual_and_tails_oracle() {
    let built = build(fixture("residual-and-tails.xml"));
    // A three-fragment residual run, the cell tail, the paragraph tail, and the
    // whitespace-only fragment.
    let expected = vec![Shape::Composite(3), Shape::Word, Shape::Word, Shape::Space];
    assert_eq!(shapes(&built.stream), expected);
}

#[test]
fn empty_structure_oracle() {
    let built = build(fixture("empty-structure.xml"));
    assert_eq!(shapes(&built.stream), vec![Shape::Word]);
}

// ----------------------------------------------------- provenance rules #

#[test]
fn every_token_carries_the_document_identity() {
    for entry in FIXTURES {
        let built = build(entry);
        let expected = identity();
        for token in &built.stream.tokens {
            assert_eq!(
                token.document_identity(),
                &expected,
                "{}: every token must bind the document identity",
                entry.file
            );
        }
        assert_eq!(built.stream.document_identity, expected);
    }
}

#[test]
fn derived_control_never_carries_a_fragment_or_span() {
    for entry in FIXTURES {
        let built = build(entry);
        for token in &built.stream.tokens {
            if let ReaderToken::DerivedControl { literal, .. } = token {
                assert!(!literal.is_empty(), "{}: derived literal", entry.file);
            }
            if let ReaderToken::Composite { units, .. } = token {
                for unit in units {
                    match unit {
                        TokenUnit::SourceSubspan { span, .. } => {
                            assert!(span.start < span.end, "{}: source sub-span", entry.file)
                        }
                        TokenUnit::DerivedControl { .. } => {}
                    }
                }
            }
        }
    }
}

#[test]
fn token_stream_is_lossless_per_view() {
    for entry in FIXTURES {
        let built = build(entry);
        let index = ReaderRecordIndex::new(built.package.records()).expect("substrate index");
        for view in &built.projection.views {
            if !view.kind.is_primary() {
                continue;
            }
            let output = built
                .order
                .view_output(&view.id)
                .expect("primary view must have an output");
            let mut rebuilt = String::new();
            for token in built.stream.tokens.iter().filter(|t| t.view() == &view.id) {
                rebuilt.push_str(&token_text(token, &index, &output));
            }
            assert_eq!(
                rebuilt, output,
                "{}: the token stream must rebuild view {}",
                entry.file, view.id
            );
        }
    }
}

// -------------------------------------------------------- read-back parity #

#[test]
fn wire_read_back_parity() {
    for entry in FIXTURES {
        let built = build(entry);
        // The direct build (projection + reading order + records) ...
        let direct = tokenize_projection(
            &built.projection,
            &built.order,
            built.package.records(),
            &identity(),
        )
        .expect("direct build must tokenize");
        // ... must equal the stream read back from the saved cleaned wire.
        let artifact = render_cleaned_projection(
            &built.package,
            &built.projection,
            &WireCompletion::Complete,
            &WireLimits::default(),
        )
        .expect("render must succeed");
        let from_wire = tokenize_from_wire(&artifact, &built.package, &identity())
            .expect("wire build must tokenize");
        assert_eq!(
            direct, from_wire,
            "{}: the wire read-back must reproduce the direct build",
            entry.file
        );
        assert_eq!(direct, built.stream);
    }
}

#[test]
fn identity_is_copied_from_the_wire_pins() {
    let built = build(fixture("text-only.xml"));
    let version = DocumentVersionRef::try_new(
        "doc-1".to_string(),
        "rev-1".to_string(),
        "reader_wordml_profile/v1".to_string(),
    )
    .expect("version must be valid");
    let identity =
        DocumentIdentity::from_cleaned(&built.cleaned, version).expect("identity must build");
    assert_eq!(identity.source.source_sha256, built.cleaned.source.sha256);
    assert_eq!(identity.source.source_bytes, built.cleaned.source.bytes);
    assert_eq!(identity.source.parent_schema, CLEANED_PROJECTION_SCHEMA);
}

// ------------------------------------------------------------- negatives #

#[test]
fn malformed_artifact_is_refused() {
    let built = build(fixture("text-only.xml"));
    let error = tokenize_from_wire("this is not a cleaned wire", &built.package, &identity())
        .expect_err("a malformed artifact must be refused");
    assert_eq!(error.kind(), TokenizerErrorKind::ArtifactUnreadable);
}

#[test]
fn unknown_view_address_is_refused() {
    let built = build(fixture("text-only.xml"));
    let address = CompositeAddress {
        view: ViewId::new("v-does-not-exist"),
        output_start: 0,
        output_end: 1,
    };
    let error = tokenize_address(&built.cleaned, &built.package, &identity(), &address)
        .expect_err("an unknown view must be refused");
    assert_eq!(error.kind(), TokenizerErrorKind::AddressRefused);
}

#[test]
fn inverted_address_is_refused() {
    let built = build(fixture("text-only.xml"));
    let view = built
        .projection
        .views
        .iter()
        .find(|view| view.kind.is_primary())
        .expect("a primary view");
    let address = CompositeAddress {
        view: view.id.clone(),
        output_start: 3,
        output_end: 3,
    };
    let error = tokenize_address(&built.cleaned, &built.package, &identity(), &address)
        .expect_err("an empty address must be refused");
    assert_eq!(error.kind(), TokenizerErrorKind::AddressRefused);
}

#[test]
fn navigation_view_address_is_refused() {
    let built = build(fixture("mixed-wordml.xml"));
    let Some(navigation) = built
        .projection
        .views
        .iter()
        .find(|view| !view.kind.is_primary())
    else {
        // The fixture need not carry a navigation view; the rule is covered by
        // the empty/inverted refusal when it does not.
        return;
    };
    let address = CompositeAddress {
        view: navigation.id.clone(),
        output_start: 0,
        output_end: 1,
    };
    let error = tokenize_address(&built.cleaned, &built.package, &identity(), &address)
        .expect_err("a navigation view must be refused");
    assert_eq!(error.kind(), TokenizerErrorKind::AddressRefused);
}

#[test]
fn out_of_bounds_address_is_refused() {
    let built = build(fixture("text-only.xml"));
    let view = built
        .projection
        .views
        .iter()
        .find(|view| view.kind.is_primary())
        .expect("a primary view");
    let address = CompositeAddress {
        view: view.id.clone(),
        output_start: 0,
        output_end: 1_000_000,
    };
    let error = tokenize_address(&built.cleaned, &built.package, &identity(), &address)
        .expect_err("an out-of-bounds address must be refused");
    assert_eq!(error.kind(), TokenizerErrorKind::AddressRefused);
}

// ---------------------------------------------------------- no re-parse #

#[test]
fn consumer_never_opens_the_source_xml() {
    // The consumer reads only materialized layers. This structural negative
    // fails if an XML parser, the substrate capture, or a source byte range
    // enters the module's non-test code.
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src/reader_tokenizer.rs");
    let source = std::fs::read_to_string(path).expect("source must be readable");
    let code_end = source.find("#[cfg(test)]").unwrap_or(source.len());
    let code: String = source[..code_end]
        .lines()
        .filter(|line| !line.trim_start().starts_with("//"))
        .collect::<Vec<_>>()
        .join("\n");
    for forbidden in [
        "quick_xml",
        "XmlReader",
        "XmlNsReader",
        "capture(",
        "from_xml",
        "parse_xml",
    ] {
        assert!(
            !code.contains(forbidden),
            "reader_tokenizer must not open the source XML, found {forbidden}"
        );
    }
}

#[test]
fn wire_build_needs_no_source_xml() {
    // `tokenize_from_wire` is given only the saved artifact and the already
    // decoded package; it never receives an XML path. The stream it produces is
    // the recorded proof that the read path is JSONL-only.
    let built = build(fixture("controls.xml"));
    let artifact = render_cleaned_projection(
        &built.package,
        &built.projection,
        &WireCompletion::Complete,
        &WireLimits::default(),
    )
    .expect("render must succeed");
    let from_wire = tokenize_from_wire(&artifact, &built.package, &identity())
        .expect("wire build must tokenize");
    assert_eq!(from_wire.composite_count(), 1);
    assert_eq!(from_wire.derived_count(), 5);
    assert_eq!(from_wire.tokens.len(), 16);
    assert_eq!(from_wire.document_identity, identity());
}
